+func (MatchClientIP) CaddyModule() caddy.ModuleInfo {
+	return caddy.ModuleInfo{
+		ID:  "http.matchers.client_ip",
+		New: func() caddy.Module { return new(MatchClientIP) },
+	}
+}
+
+// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
+func (m *MatchClientIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
+	parsed := MatchRemoteIP{
+		Ranges: m.Ranges,
+		cidrs:  m.cidrs,
+		zones:  m.zones,
+		logger: m.logger,
+	}
+	err := parsed.unmarshalIPRanges(d, "client_ip", false)
+	m.Ranges = parsed.Ranges
+	m.cidrs = parsed.cidrs
+	return err
+}
+
+func (m *MatchRemoteIP) unmarshalIPRanges(d *caddyfile.Dispenser, matcherName string, rejectForwarded bool) error {
+	d.Next() // consume matcher name
+	tokens := d.Tokens()
+	for d.NextArg() {
+		cursor := d.Cursor()
+		if cursor < 0 || cursor >= len(tokens) {
+			break
+		}
+		tok := tokens[cursor]
+		origin := tok.File + ":" + fmt.Sprintf("%d", tok.Line+tok.NumLineBreaks())
+		if !caddyfile.ValidImportSequence(origin, tok.ImportChain()) {
+			return d.Err("invalid import chain")
+		}
+		val := tok.Text
+		if rejectForwarded && val == "forwarded" {
+			return d.Err("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
+		}
+		if val == "private_ranges" {
+			private := StaticIPRange{Ranges: PrivateRangesCIDR()}
+			m.Ranges = append(m.Ranges, private.Ranges...)
+			continue
+		}
+		m.Ranges = append(m.Ranges, val)
+	}
